#define smoothness 5
#define nowaves 1
float smoothP(float pos,int channel) {
    //smooth sound points
    float value = 0.;
    for (int x = -smoothness;x <= smoothness;x++) {
        value += fetchData(iChannel0,ivec2(pos + float(x),channel)).r;
    }
    return value / float(smoothness*2);
}
vec3 lerp(vec3 a,vec3 b,float time) {
    return a * (1.-time) + b * time;
}
float getHighest() {
    float current = 0.;
    for (int p = 0;p <= int(iResolution.x);p++) {
        if (fetchData(iChannel0,ivec2(p,0)).r > current) {
            current = fetchData(iChannel0,ivec2(p,0)).r;
        }
    }
    return current;
}
float getLowest() {
    float current = 10000000000000.;
    for (int p = 0;p <= int(iResolution.x);p++) {
        if (fetchData(iChannel0,ivec2(p,0)).r < current) {
            current = fetchData(iChannel0,ivec2(p,0)).r;
        }
    }
    return current;
}
vec3 style1(float height,vec2 uv) {
    return lerp(vec3(1,0.5,0),vec3(1,0,0),uv.y);
}
vec3 style2(float height,vec2 uv) {
    return lerp(vec3(1,0.5,0),vec3(1,0,0),height);
}
vec3 style3(float height,vec2 uv) {
    return lerp(vec3(1,0.5,0),vec3(1,0,0),uv.x);
}
vec3 style4(float height,vec2 uv) {
    float highest = getHighest();
    return lerp(vec3(1,0.5,0),vec3(1,0,0),height/highest);
}
vec3 style5(float height,vec2 uv) {
    float highest = getHighest();
    return lerp(vec3(1,0.5,0),vec3(1,0,0),1. - height/highest);
}
vec3 style6(float height,vec2 uv) {
    return lerp(vec3(1,0.5,0),vec3(1,0,0),sin(iTime)*uv.y);
}
vec3 style7(float height,vec2 uv) {
    return lerp(vec3(1,0.5,0),vec3(1,0,0),sin(iTime)*uv.x);
}
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    //float height = fetchData(iChannel0,ivec2(fragCoord.x,0)).r;
    int counter = int(mod(iTime,70.)/10.);
    float height = smoothP(fragCoord.x,0);
    vec3 col;
    if (counter == 0 ) {
    col = style1(height,uv);
    } else if (counter == 1) {
    col = style2(height,uv);
    } else if (counter == 2) {
    col = style3(height,uv);
    } else if (counter == 3) {
    col = style4(height,uv);
    } else if (counter == 4) {
    col = style5(height,uv);
    } else if (counter == 5) {
    col = style6(height,uv);
    } else {
    col = style7(height,uv);
    }
    #ifndef nowaves
    vec3 col2;
    float height2 = smoothP(fragCoord.x,1);
    if (counter == 0 ) {
    col2 = style1(height2,uv);
    } else if (counter == 1) {
    col2 = style2(height2,uv);
    } else if (counter == 2) {
    col2 = style3(height2,uv);
    } else if (counter == 3) {
    col2 = style4(height2,uv);
    } else if (counter == 4) {
    col2 = style5(height2,uv);
    } else if (counter == 5) {
    col2 = style6(height2,uv);
    } else {
    col2 = style7(height2,uv);
    }
    col2 += vec3(0,0,0.25);
    col2 *= vec3(0.5,0.9,3);
    if (uv.y < height && uv.y < height2) {
        fragColor = vec4(mix(col,col2,0.5),1.0);
    } else if (uv.y < height) {
        fragColor = vec4(col,1.0);
    } else if (uv.y < height2) {
        fragColor = vec4(col2,1.0);
    } else {
        fragColor = vec4(0,0,0,1);
    }
    #else
    if (uv.y < height) {
        fragColor = vec4(col,1.0);
    } else {
        fragColor = vec4(0,0,0,1);
    }
    #endif
}
